div.script:
(function () {
    var box = document.getElementById('eb-downloads');
    if (!box) { return; }
    function size(n) { return (Math.round(n / 1048576 * 10) / 10) + ' MB'; }
    function el(tag, cls, text, parent) {
        var e = document.createElement(tag);
        if (cls) { e.className = cls; }
        if (text) { e.textContent = text; }
        if (parent) { parent.appendChild(e); }
        return e;
    }
    fetch('/descargas-files/index.json', {cache: 'no-cache'}).then(function (r) { return r.json(); }).then(function (data) {
        box.textContent = '';
        (data.items || []).forEach(function (it) {
            var card = el('div', 'eb-card', '', box);
            el('h3', '', it.name, card).style.marginTop = '0';
            el('span', 'eb-tag', it.platform, el('p', '', '', card));
            el('p', '', it.description, card);
            var meta = el('p', '', 'Versión ' + it.version + ' · ' + size(it.size) + ' · ' + (it.updated || '').slice(0, 10), card);
            meta.style.fontSize = '.88rem';
            var a = el('a', 'eb-btn eb-btn-main', 'Descargar ↓', card);
            a.href = it.url;
            a.setAttribute('download', '');
            var sha = el('p', 'eb-muted', 'SHA-256: ' + it.sha256, card);
            sha.style.cssText = 'margin:12px 0 0;font-size:.72rem;word-break:break-all;';
        });
        if (!box.firstChild) { box.textContent = 'Pronto habrá descargas disponibles.'; }
    }).catch(function () {
        box.textContent = 'No se pudo cargar la lista. Intenta de nuevo en unos minutos.';
    });
})();
